def count_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i*i == n:
                count += 1
            else:
                count += 2
    return count

n = 2310
tau_n = count_divisors(n)
print(f"tau({n}) = {tau_n}")

import math

K = 2310
alpha = math.sqrt(2)

# Divisors of 2310 less than or equal to 10
divisors_m = [1, 2, 3, 5, 6, 7, 10]

pretty_pairs = []

print(f"Testing for pretty pairs (m, n) for k={K} and alpha={alpha:.4f} in range m<=10, 1<=n<=20.")

for m in divisors_m:
    for n in range(1, 21):
        # Pretty condition: m*ceil(n*alpha) - n*floor(m*alpha) = K
        try:
            lhs = m * math.ceil(n * alpha) - n * math.floor(m * alpha)

            if lhs == K:
                is_pretty = True
                pretty_pairs.append((m, n))
                print(f"FOUND pretty pair: ({m}, {n}). LHS = {lhs}")

                # Check Cool constraints if pretty pair found
                m_cool, n_cool = m, n

                # 1. Exclusion of (m-n, n)
                m1, n1 = m - n, n
                if m1 > 0:
                    lhs1 = m1 * math.ceil(n1 * alpha) - n1 * math.floor(m1 * alpha)
                    is_cool_1 = (lhs1 != K)

                    # 2. Exclusion of (m, n-m)
                    m2, n2 = m, n - m
                    if n2 > 0:
                        lhs2 = m2 * math.ceil(n2 * alpha) - n2 * math.floor(m2 * alpha)
                        is_cool_2 = (lhs2 != K)

                        if is_cool_1 and is_cool_2:
                            print(f"-> Confirmed COOL pair: ({m}, {n}).")
                        else:
                            print(f"-> Not cool: Fails constraint 1 ({lhs1} == {K}) or constraint 2 ({lhs2} == {K}).")
                    else:
                        print(f"-> Not cool: Fails constraint 2 (n-m <= 0).")
                else:
                    # m-n <= 0, so (m-n, n) is not a positive pair, automatically satisfies condition 1.
                    # Check condition 2
                    m2, n2 = m, n - m
                    if n2 > 0:
                        lhs2 = m2 * math.ceil(n2 * alpha) - n2 * math.floor(m2 * alpha)
                        if lhs2 != K:
                            print(f"-> Confirmed COOL pair: ({m}, {n}). (m-n <= 0)")
                        else:
                            print(f"-> Not cool: Fails constraint 2 ({lhs2} == {K}).")
                    else:
                        print(f"-> Not cool: Fails constraint 2 (n-m <= 0).")
        except OverflowError:
            # Should not happen with standard floats for these ranges, but good practice.
            pass

if not pretty_pairs:
    print("\nNo pretty pairs were found in the tested range.")
else:
    print(f"\nTotal pretty pairs found: {len(pretty_pairs)}")
